/* PLAY-13 (владелец, 27 ноября): один значок входа для всех подземелий; размер от ширины карты (10%, 44–60 px) вместо 72×55, зеркалирование по карте — DUNGEON_ENTRY_FLIP[зона]. Арт не меняется; CSS добавляется здесь, чтобы не трогать styles-27 (проверка CSS по эталону). */
  const DUNGEON_ENTRY_FLIP = Object.freeze({ westfall: false });
  function dmEntranceStyle(){if(document.getElementById('az-dm-entry-size'))return;const s=document.createElement('style');s.id='az-dm-entry-size';s.textContent='#dm-map-entry{width:clamp(44px,10%,60px)!important;height:auto!important;aspect-ratio:72/55}#dm-map-entry .mk{width:100%!important;height:100%!important}#dm-map-entry[data-flip] .mk{transform:scaleX(-1)!important}';document.head.appendChild(s);}
  function dmEntranceHtml(){const p=PLACES.deadm;if(!p||(S.mapZ||viewZone())!==p.z)return '';dmEntranceStyle();return '<button type="button" id="dm-map-entry" class="qn grp" data-dungeon-entry="deadmines"'+(DUNGEON_ENTRY_FLIP[p.z]?' data-flip=""':'')+' style="left:'+p.x+'%;top:'+p.y+'%"
